 * ID           :	ULDSTF09340
 * File         :	ULDSTF09340.xml
 * Name         :	투자유의
 * Author       :	배성우
 * Description  :	상장형수익증권 투자유의
 * Create Date  :	2026-09-15
************************************************************************************/

scwin.vScrenID = "ULDSTF09340.xml";
scwin.fr_MktId = $c.session.getUserInfo("market");
// scwin.fr_SecuGrpId = $c.lc.getSecuGrpId($c.stf.InfoMenuID());
scwin.isurCd = "", scwin.isurNm = "", scwin.isuCd = "", scwin.isuNm = "", scwin.vBzProcsNo = "", scwin.select_gubun = "3", scwin.todayDd = "";
scwin.calDd = "", scwin.fstDtectDd = "", scwin.inqDd = "", scwin.designDd = "";

scwin.fr_SecuGrpId = "PF"; //상장형수익증권
scwin.fn_GetPar, scwin.fn_SetPar;

// 탭 변경시 첫화면인 경우만 적용
scwin.isFirst1 = true;
scwin.isFirst2 = true;
scwin.isFirst3 = true;
scwin.isFirst4 = true;
scwin.isFirst5 = true;
scwin.isFirst6 = true;

scwin.onpageload = function() {
    scwin.init();
};

scwin.onpageunload = function() {
};

/* 
 * 화면 초기화
 */
scwin.init = async function() {
    btn_regist.hide();
    $c.win.setEnterKeyEvent(pan_cmd1, scwin.btn_search1_onclick);
    $c.win.setEnterKeyEvent(pan_cmd2, scwin.btn_search2_onclick);
    $c.win.setEnterKeyEvent(pan_cmd3, scwin.btn_search3_onclick);
    $c.win.setEnterKeyEvent(pan_cmd4, scwin.btn_search4_onclick);
    $c.win.setEnterKeyEvent(pan_cmd5, scwin.btn_search5_onclick);
    $c.win.setEnterKeyEvent(pan_cmd6, scwin.btn_search6_onclick);
    $c.date.checkCalendarFormat(cal_searchDate1, "yyyyMMdd");

    sbx_registType.hide();
    tbx_registType.setValue("");

    await scwin.fn_today_dd();
    await scwin.fn_cal_dd();
    // MaxTab_1.setSelectedTabIndex(0);
};

/* 
 * 오늘날짜 조회 (api 대신 server 날짜로 하면 되지않을까)
 */
scwin.fn_today_dd = function() {
    // var url = "/listingCommon.do?method=listGeneral&outputMessageId=PF_INVSTWARN_DATE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.pf.lstproc.invstwarn_today_dd.select";
    // dma_cand.DataID = encodeURI(url);
    // dma_cand.reset();
    // scwin.todayDd = dma_cand.getCellData(1, "TODAY_DD");

    scwin.todayDd = $c.date.getServerDateTime();
    cal_searchDate1.setValue(scwin.todayDd);
};

/* 
 * 익영업일 조회
 */
scwin.fn_cal_dd = async function() {

    const sbmOptions = {
        id: "sbm_nextday",
        action: "/api/listing/lstproc/pf/invst-warn/select-nextday",
        method: "get",
        target: "dma_cand=body",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {
        scwin.calDd = dma_cand.get("nextDd");
    }
};

/* 
 * 조회 전 마감/진행상태 조회(fn_invstwarn_cls) 하는 API
 */
scwin.fn_invstwarn_cls = async function() {
    var trd_dd = "";
    switch (MaxTab_1.getSelectedTabIndex()) {
        case 0:
            trd_dd = $c.stf.getObjectValue(cal_searchDate1);
            break;
        case 1:
            trd_dd = $c.stf.getObjectValue(cal_searchDate2);
            break;
        case 2:
            trd_dd = $c.stf.getObjectValue(cal_searchDate3);
            break;
        case 3:
            trd_dd = $c.stf.getObjectValue(cal_searchDate4);
            break;
        case 4:
            trd_dd = $c.stf.getObjectValue(cal_searchDate5);
            break;
        case 5:
            trd_dd = $c.stf.getObjectValue(cal_searchDate6);
            break;
    }

    const reqMap = {
        progsDd: trd_dd, //처리일자
        trdDd: trd_dd, //거래일자
    }
    const sbmOptions = {
        id: "sbm_cls",
        action: "/api/listing/lstproc/pf/invst-warn/select-md-progm-prog",
        method: "get",
        target: "dma_cls=body",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);
    if (res.responseJSON.success) {
        ibx_clsDtl.setValue(dma_cls.get("clsYn"));
    }
};

/* 
 * 목록 조회
 */
scwin.fn_search = function() {
    switch (MaxTab_1.getSelectedTabIndex()) {
        case 0:
            scwin.fn_search_1();
            break;
        case 1:
            scwin.fn_search_2();
            break;
        case 2:
            scwin.fn_search_3();
            break;
        case 3:
            scwin.fn_search_4();
            break;
        case 4:
            scwin.fn_search_5();
            break;
        case 5:
            scwin.fn_search_6();
            break;
    }
};

//최초적출 조회
scwin.fn_search_1 = async function() {
    if ($c.stf.getObjectValue(cal_searchDate1) === "") {
        await $c.win.alert($c.data.getMessage("com_req_input", "조회일자"));
        cal_searchDate1.focus();
        return;
    }

    await scwin.fn_invstwarn_cls();
    const reqMap = {
        trdDd: cal_searchDate1.getValue(), //조회일자
        secugrpId: scwin.fr_SecuGrpId, //증권그룹ID
        gubunCd: "01", //구분코드
    }
    const sbmOptions = {
        id: "sbm_selectList1",
        action: "/api/listing/lstproc/pf/invst-warn/select-list",
        method: "get",
        target: "dlt_selectList1=body",
        gridview: "grd_1",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);
    if (res.responseJSON.success) {
        tbx_totCnt.setValue(dlt_selectList1.getRowCount());
    }
};

