/* 
 * 최초적출 신규
 */
scwin.fn_new_create_frame_1 = async function(param) {
    const opts = {
        id: "ULDSTF09341",
        popupName: $c.lc.getSecuGrpNm(scwin.fr_SecuGrpId) + " 투자유의종목 최초적출",
        width: 800,
        height: 650,
        frameModal: "top",
        type: "pageFramePopup",
    };
    const res = await $c.win.openPopup("/ui/lst/pf/ULDSTF09341.xml", opts, param);
    await scwin.btn_search1_onclick();
};

