/* 
 * 매매거래정지 및 정지해제 신규
 */
scwin.fn_new_create_frame_6 = async function() {
    if (sbx_registType.getSelectedIndex() === 0) {
        await $c.win.alert($c.data.getMessage("com_req_select", "신규등록구분"));
        sbx_registType.focus();
        return true;
    }
    // scwin.fn_GetPar = fn_GetParNewTrdHalt;
    // scwin.fn_SetPar = undefined;
    scwin.fn_new_create_frame_trdHalt(sbx_registType.getValue(), "");
};

/* 
 * 매매거래정지 및 정지해제 신규 팝업
 */
scwin.fn_new_create_frame_trdHalt = async function(arg, startDd) {
    let popId = "";
    let popNm = "";
    let height = 800;
    /*
    0:지정, 1:해제, 2:지정및해제(유), 3:지정->해제
    */
    switch (arg) {
        case "0":
            popId = "ULDSTF09043";
            popNm = $c.lc.getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정";
            height = 800;
            break;
        case "1":
            popId = "ULDSTF09044";
            popNm = $c.lc.getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 해제";
            height = 820;
            break;
        case "2":
            popId = "ULDSTF09042";
            popNm = $c.lc.getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정 및 해제";
            height = 900;
            break;
    }
    const param = {};
    await scwin.fn_GetParNewTrdHalt(param);

    const opts = {
        id: popId,
        popupName: popNm,
        width: 850,
        height: height,
        frameModal: "top",
        type: "pageFramePopup",
    };
    const res = await $c.win.openPopup("/ui/lst/pf/"+ popId +".xml", opts, param);
    sbx_registType.setSelectedIndex(0);
};

/* 
 * 매매거래정지 및 정지해제 수정 팝업
 */
scwin.fn_update_create_frame_trdHalt = async function(arg, startDd) {

    if (arg == "") arg = "2"; // arg -> haltDesnrelsTpCd 없는 경우, 임시 방어로직 추가 (저장할 때 제대로 입력하면 조회때도 나올것 같음)

    if (arg == "1" && startDd != "") arg = "3";

    let popId = "";
    let popNm = "";
    let height = 800;
    /*
    0:지정, 1:해제, 2:지정및해제(유), 3:지정->해제
    */
    switch (arg) {
        case "0":
            popId = "ULDSTF09043";
            popNm = $c.lc.getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정";
            height = 800;
            break;
        case "1":
            popId = "ULDSTF09044";
            popNm = $c.lc.getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 해제";
            height = 900;
            break;
        case "2":
            popId = "ULDSTF09042";
            popNm = $c.lc.getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정 및 해제";
            height = 820;
            break;
        case "3":
            popId = "ULDSTF09044";
            popNm = $c.lc.getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 해제";
            height = 900;
            break;
    }

    const param = {};
    await scwin.fn_GetParUpdateTrdHalt(param);

    const opts = {
        id: popId,
        popupName: popNm,
        width: 850,
        height: height,
        frameModal: "top",
        type: "pageFramePopup",
    };
    const res = await $c.win.openPopup("/ui/lst/pf/"+ popId +".xml", opts, param);
    sbx_registType.setSelectedIndex(0);
};

