/* 
 * 매매거래정지 신규 파라메터
 */
scwin.fn_GetParNewTrdHalt = function(arrPar) {
    // 넘길 인수를 지정하는 펑션

    // arrPar[0] = scwin.isurCd;
    // arrPar[1] = scwin.isurNm;
    // arrPar[2] = scwin.fr_SecuGrpId;
    // arrPar[3] = scwin.fr_MktId;
    // arrPar[4] = "";
    // arrPar[5] = sbx_registType.getValue();
    // arrPar[6] = ""; // 종목코드
    // arrPar[7] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)				

    // arrPar[8] = scwin.fstDtectDd; //최초지정일
    // arrPar[9] = scwin.designDd; //매매거래정지일
    // arrPar[10] = scwin.inqDd; //조회일 
    // arrPar[11] = "424";
    // arrPar[12] = "투자유의종목(상장형 수익증권)";
    // arrPar[13] = "";

    arrPar.isurCd = scwin.isurCd;
    arrPar.isurNm = scwin.isurNm;
    arrPar.secugrpId = scwin.fr_SecuGrpId;
    arrPar.fr_MktId = scwin.fr_MktId;
    arrPar.bzProcsNo = "";
    arrPar.haltTpCd = sbx_registType.getValue();
    arrPar.gubun = ""; // 종목코드
