/* 
 * [최초적출] 목록 더블클릭
 */
scwin.grd_1_oncelldblclick = async function (row, columnIndex, columnId) {
    if (row < 0) {
        return; //목록 조회 완료보다 더 빠르게 더블클릭하면 데이터가 없는 경우가 있어서 체크
    }
    scwin.vBzProcsNo = dlt_selectList1.getCellData(row, "bzProcsNo");
    scwin.isuCd = dlt_selectList1.getCellData(row, "isuCd");
    scwin.isuNm = dlt_selectList1.getCellData(row, "isuNm");
    scwin.isurCd = dlt_selectList1.getCellData(row, "isurCd");
    scwin.isurNm = "";
    scwin.fstDtectDd = dlt_selectList1.getCellData(row, "fstDtecDd");
    scwin.inqDd = $c.stf.getObjectValue(cal_searchDate1);
    scwin.designDd = scwin.inqDd;
    let param = {};
    if (scwin.vBzProcsNo == "") {
        await scwin.fn_GetParNew(param);
    } else {
        await scwin.fn_GetParUpdate(param);
    }
    scwin.fn_new_create_frame_1(param);
};

