/* 
 * [매매거래정지 및 정지해제] 목록 더블클릭
 */
scwin.grd_6_oncelldblclick = async function (row, columnIndex, columnId) {
    if (row < 0) {
        return; //목록 조회 완료보다 더 빠르게 더블클릭하면 데이터가 없는 경우가 있어서 체크
    }
    scwin.vBzProcsNo = dlt_selectList6.getCellData(row, "bzProcsNo");
    scwin.isuCd = dlt_selectList6.getCellData(row, "isuCd");
    scwin.isuNm = dlt_selectList6.getCellData(row, "isuNm");
    scwin.isurCd = dlt_selectList6.getCellData(row, "isurCd");
    scwin.isurNm = dlt_selectList6.getCellData(row, "isurNm");
    scwin.fstDtectDd = dlt_selectList6.getCellData(row, "fstDtecDd");
    scwin.inqDd = $c.stf.getObjectValue(cal_searchDate6);
    scwin.designDd = scwin.calDd;
    let param = {};
    if (scwin.vBzProcsNo == "" && dlt_selectList6.getCellData(row, "haltDesnrelsTpCd") == "1") {
        //종목해제인경우
        var url = "/listingCommon.do?method=listGeneral&outputMessageId=PF_TRD_SUSP_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.pf.invstwarn.halt_desnrels_0.select" + "&{P}param01=" + scwin.isuCd + "&{P}param02=" + scwin.fstDtectDd;
        dset_haltRealese.DataID = encodeURI(url);
        dset_haltRealese.reset();
        scwin.vBzProcsNo = dset_haltRealese.getCellData(1, "bzProcsNo");
        await scwin.fn_GetParRelease(param);
    } else {
        scwin.vBzProcsNo = dlt_selectList6.getCellData(row, "bzProcsNo");
        if (scwin.vBzProcsNo == "") {
            await scwin.fn_GetParNewTrdHalt(param);
        } else {
            await scwin.fn_GetParUpdateTrdHalt(param); //매매거래정지
        }
    }
    if (scwin.vBzProcsNo != "") {
        scwin.fn_update_create_frame_trdHalt(dlt_selectList6.getCellData(row, "haltDesnrelsTpCd"), dlt_selectList6.getCellData(row, "trdHaltStrtDd"));
    } else {
        if (dlt_selectList6.getCellData(row, "haltDesnrelsTpCd") == '0') {
            //정지
            if (sbx_registType.getValue() != '0') {
                //정지 
                sbx_registType.setValue("2"); //지정 및 해제 
            }
            scwin.fn_new_create_frame_trdHalt(sbx_registType.getValue(), "");
        } else {
            sbx_registType.setValue(dlt_selectList6.getCellData(row, "haltDesnrelsTpCd"));
            scwin.fn_new_create_frame_trdHalt(dlt_selectList6.getCellData(row, "haltDesnrelsTpCd"), "");
        }
    }
};

/* 
 * 탭 변경
 * (tabIndex는 0부터 시작)
 */
scwin.MaxTab_1_onchange = async function (tabId, index, userTabId) {

    switch (MaxTab_1.getSelectedTabIndex()) {
        case 0:
            if (scwin.isFirst1) {
                cal_searchDate1.setValue(scwin.todayDd);
                scwin.isFirst1 = false;
            }
            btn_regist.hide();
            break;
        case 1:
            if (scwin.isFirst2) {
                cal_searchDate2.setValue(scwin.todayDd);
                $c.date.checkCalendarFormat(cal_searchDate2, "yyyyMMdd");
                scwin.isFirst2 = false;
            }
            btn_regist.hide();
            break;
        case 2:
            if (scwin.isFirst3) {
                cal_searchDate3.setValue(scwin.todayDd);
                $c.date.checkCalendarFormat(cal_searchDate3, "yyyyMMdd");
                scwin.isFirst3 = false;
            }
            btn_regist.show("");
            break;
        case 3:
            if (scwin.isFirst4) {
                cal_searchDate4.setValue(scwin.todayDd);
                $c.date.checkCalendarFormat(cal_searchDate4, "yyyyMMdd");
                scwin.isFirst4 = false;
            }
            btn_regist.show("");
            break;
        case 4:
            if (scwin.isFirst5) {
                cal_searchDate5.setValue(scwin.todayDd);
                $c.date.checkCalendarFormat(cal_searchDate5, "yyyyMMdd");
                scwin.isFirst5 = false;
            }
            btn_regist.show("");
            break;
        case 5:
            if (scwin.isFirst6) {
                cal_searchDate6.setValue(scwin.todayDd);
                $c.date.checkCalendarFormat(cal_searchDate6, "yyyyMMdd");
                scwin.isFirst6 = false;
            }
            btn_regist.show("");
            break;
    }
    if (MaxTab_1.getSelectedTabIndex() === 5) {
        sbx_registType.show("");
        tbx_registType.setValue("");
    } else {
        sbx_registType.hide();
        tbx_registType.setValue("");
    }
    await scwin.fn_search();
};

