/* 
 * 신규 버튼
 */
scwin.btn_regist_onclick = async function() {
    scwin.isuCd = "";
    scwin.isuNm = "";
    scwin.isurCd = "";
    scwin.isurNm = "";
    scwin.fstDtectDd = "";
    switch (MaxTab_1.getSelectedTabIndex()) {
        case 0:
            scwin.inqDd = $c.stf.getObjectValue(cal_searchDate1);
            scwin.designDd = scwin.inqDd;
            break;
        case 1:
            scwin.inqDd = $c.stf.getObjectValue(cal_searchDate2);
            scwin.designDd = scwin.calDd;
            break;
        case 2:
            scwin.inqDd = $c.stf.getObjectValue(cal_searchDate3);
            scwin.designDd = scwin.calDd;
            break;
        case 3:
            scwin.inqDd = $c.stf.getObjectValue(cal_searchDate4);
            scwin.designDd = scwin.calDd;
            break;
        case 4:
            scwin.inqDd = $c.stf.getObjectValue(cal_searchDate5);
            scwin.designDd = scwin.calDd;
            break;
        case 5:
            scwin.inqDd = $c.stf.getObjectValue(cal_searchDate6);
            scwin.designDd = scwin.calDd;
            break;
    }
    if (scwin.inqDd < scwin.todayDd) {
        $c.win.alert("과거 조회일자인 경우 조회만 가능합니다.");
        return;
    }
    // scwin.fn_GetPar = fn_GetParNew;
    // scwin.fn_SetPar = undefined;
    let param = {};
    await scwin.fn_GetParNew(param);
    switch (MaxTab_1.getSelectedTabIndex()) {
        case 0:
            scwin.fn_new_create_frame_1(param);
            break;
        case 1:
            scwin.fn_new_create_frame_2(param);
            break;
        case 2:
            scwin.fn_new_create_frame_3(param);
            break;
        case 3:
            scwin.fn_new_create_frame_4(param);
            break;
        case 4:
            scwin.fn_new_create_frame_5(param);
            break;
        case 5:
            scwin.fn_new_create_frame_6(param);
            break;
    }
};

